mapper.select:
SELECT algorithm_id, algorithm_code, algorithm_name,algorithm_description,confidence,model_config
FROM vm_algorithm_info_t
WHERE delete_flag = '0' AND algorithm_code = #{algorithmCode}

SELECT DISTINCT(t1.algorithm_code) algorithmCode, t2.algorithm_name algorithmName, t4.type_value alarmType, t4.type_name typeName FROM vm_order_algorithms t1 LEFT JOIN vm_algorithm_info_t t2 ON t1.algorithm_code = t2.algorithm_code LEFT JOIN vm_algorithm_alarm t3 ON t2.algo_min_type_code = t3.algo_min_type LEFT JOIN sys_alarm_type t4 ON t3.alarm_type = t4.type_value WHERE t1.delete_flag = 0 AND t2.delete_flag = 0 AND t3.delete_flag = '0' AND t4.delete_flag = 0 AND t1.ord_status IN (0,1,2)
AND t2.app_scenarios = #{appScenarios}
${dataScope}

SELECT DISTINCT t5.algorithm_code algorithmCode, t2.algorithm_name algorithmName, t4.type_value alarmType, t4.type_name typeName FROM vm_order_devices t1 LEFT JOIN vm_order_algorithms t5 ON t5.order_code = t1.order_code AND t5.package_code = t1.package_code LEFT JOIN vm_algorithm_info_t t2 ON t5.algorithm_code = t2.algorithm_code LEFT JOIN vm_algorithm_alarm t3 ON t2.algo_min_type_code = t3.algo_min_type LEFT JOIN sys_alarm_type t4 ON t3.alarm_type = t4.type_value WHERE t1.delete_flag = 0 AND t2.delete_flag = 0 AND t3.delete_flag = '0' AND t4.delete_flag = 0 AND t5.delete_flag = 0 AND t1.ord_status IN (0,1,2) AND t2.app_scenarios = '1'
AND t1.device_code = #{deviceCode}
and t1.device_code IN
#{item}
${dataScope}

SELECT DISTINCT t5.algorithm_code algorithmCode, t5.algorithm_name algorithmName, t4.type_value alarmType, t4.type_name typeName, t1.device_code, '0' AS algorithmType, t5.status FROM vm_algorithm_config t5 LEFT JOIN vm_order_devices t1 ON t1.device_code = t5.device_code AND t1.delete_flag = 0 AND t5.delete_flag = 0 LEFT JOIN vm_algorithm_info_t t2 ON t5.algorithm_code = t2.algorithm_code AND t2.delete_flag = '0' LEFT JOIN vm_algorithm_alarm t3 ON t2.algo_min_type_code = t3.algo_min_type AND t3.delete_flag = '0' LEFT JOIN sys_alarm_type t4 ON t3.alarm_type = t4.type_value AND t4.delete_flag = 0 WHERE t1.ord_status IN (0,1,2) AND t2.app_scenarios = '1'
and t1.device_code IN
#{item}
${dataScope}

SELECT DISTINCT t5.algorithm_code algorithmCode, t5.algorithm_name algorithmName, t5.alarm_type alarmType, t5.alarm_type_name typeName, t1.device_code, '1' AS algorithmType, t5.STATUS FROM vm_algorithm_give_config t5 LEFT JOIN vm_order_devices t1 ON t1.device_code = t5.device_code AND t1.delete_flag = 0 AND t5.delete_flag = 0 WHERE t1.ord_status IN (0,1,2)
and t1.device_code IN
#{item}
${dataScope}

SELECT DISTINCT(t1.algorithm_code) algorithmCode, t2.algorithm_name algorithmName, t4.type_value alarmType, t4.type_name typeName, t2.extend_json extendJson FROM vm_order_algorithms t1 LEFT JOIN vm_algorithm_info_t t2 ON t1.algorithm_code = t2.algorithm_code LEFT JOIN vm_algorithm_alarm t3 ON t2.algo_min_type_code = t3.algo_min_type LEFT JOIN sys_alarm_type t4 ON t3.alarm_type = t4.type_value WHERE t1.delete_flag = 0 AND t2.delete_flag = 0 AND t3.delete_flag = '0' AND t4.delete_flag = 0 AND t1.ord_status IN (0,1,2)
AND t2.app_scenarios = #{appScenarios}
${dataScope}

SELECT scene_id, scene_name FROM sys_scene_config WHERE delete_flag = 0
AND scene_id IN
#{item}

SELECT config_id, algorithm_code, model_config, points, oil_gas_pipelines, trip_thread, text_labels, tenant_id, industry_code, time_interval, time_interval_unit, analysis_period FROM vm_algorithm_config WHERE delete_flag = '0' AND algorithm_code IN ( SELECT DISTINCT algorithm_code FROM vm_algorithm_info_t WHERE delete_flag = '0' AND algorithm_model_type = '2' ) AND scene_code IS NULL
and config_id IN
#{item}
